<?php
$isNew=isset($_GET['new']); $id=$_GET['id']??''; $record=$isNew ? ac_blank_record() : ($id!=='' ? ac_find_record($id) : null);
if(!$record){ ac_hero('Record not found','Record Detail','No record matched the requested ID. Return to Records or create a new owner-managed record.'); echo '<p><a class="button" href="?page=records">Back to Records</a> <a class="button" href="?page=record-detail&new=1">Add record</a></p>'; return; }
ac_hero($isNew?'Create record':'Granular edit','Record Detail: '.$record['record_id'],'Edit the owner-managed JSON overlay. SSOT seed files remain read-only; saves are stored in the owner arena JSON storage layer.');
?><?php ac_record_detail_panel($record); ?><section class="grid two"><article class="panel"><h2>Source and gate</h2><p><?= ac_pill($record['source_type']) ?> <?= ac_pill(ac_public_gate($record),'gate') ?></p><p>Source document: <code><?= ac_e($record['source_file']) ?></code></p><p>Last updated/freshness: <?= ac_e($record['last_updated']) ?></p></article><article class="panel"><h2>Related files / records</h2><h3>Files</h3><ul><?php foreach($record['linked_files'] as $f) echo '<li><code>'.ac_e($f).'</code></li>'; ?></ul><h3>Records</h3><ul><?php foreach($record['linked_records'] as $f) echo '<li>'.ac_e($f).'</li>'; ?></ul></article></section><?php ac_record_form($record,$isNew); ?>
